mapper.select:
SELECT a.id, a.appoint_no, a.visitor_id, v.name AS visitorName, v.phone AS visitorPhone, a.host_id, u.real_name AS hostName, u.dept_name AS hostDept, a.visit_type, a.purpose, a.expected_arrive, a.expected_leave, a.status, a.approved_by, a.approved_at, a.reject_reason, a.reschedule_from, a.created_at, pc.code AS passCode, pc.status AS passCodeStatus FROM appointment a LEFT JOIN visitor v ON a.visitor_id = v.id LEFT JOIN sys_user u ON a.host_id = u.id LEFT JOIN pass_code pc ON a.id = pc.appointment_id
AND a.host_id = #{hostId}
AND a.status = #{status}
AND (v.name LIKE CONCAT('%', #{keyword}, '%') OR a.appoint_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.created_at DESC

SELECT COUNT(*) FROM appointment
WHERE visitor_id = #{visitorId}
  AND host_id = #{hostId}
  AND status NOT IN ('CANCELLED', 'REJECTED', 'EXPIRED', 'COMPLETED')
  AND expected_arrive < #{endTime}
  AND (expected_leave IS NULL OR expected_leave > #{startTime})

      AND id != #{excludeId}

SELECT * FROM appointment
WHERE status = 'PENDING'
  AND expected_arrive < #{now}
